[CmdletBinding()]
param([string]$InstallRoot="$env:ProgramData\PDCMonitor\Staging",[switch]$DryRun)
$ErrorActionPreference='Stop';$v='2026.08.66';$control=Join-Path $InstallRoot "control\$v";$trust=Join-Path $InstallRoot "trust\$v";$dispatch=Join-Path $control 'run-current-active.ps1';if((Get-Content (Join-Path $InstallRoot 'CURRENT') -Raw).Trim() -ne $v){throw 'PDC_MONITOR_SUCCESSOR_ACTIVE_BOOTSTRAP_CURRENT_MISMATCH'};if((Get-FileHash $dispatch -Algorithm SHA256).Hash.ToLower() -ne (Get-Content (Join-Path $trust 'ACTIVE_DISPATCH_SHA256') -Raw).Trim().ToLower()){throw 'PDC_MONITOR_SUCCESSOR_ACTIVE_BOOTSTRAP_DISPATCH_HASH_MISMATCH'};if($DryRun){& $dispatch -InstallRoot $InstallRoot -Mode OneCycle -DryRun}else{& $dispatch -InstallRoot $InstallRoot -Mode OneCycle};exit $LASTEXITCODE
